    explanation: 'Fixed windows allow bursts at boundaries (e.g., 100 req/min: 100 requests at 11:59, 100 at 12:00 = 200 in 1 second). Sliding window log tracks each request timestamp, guaranteeing the rate over the last N seconds. Redis sorted sets enable O(log N) insertion and count. Lua scripting ensures atomicity. Rate limit violation returns 429 with Retry-After header. Different rate limit tiers (free/pro) have different rules applied via tier lookup.',
