    explanation: 'Consumer offset tracks which message the consumer has read. With auto.commit, Kafka commits the position periodically (default every 5s). If the consumer crashes between a commit and the next poll, messages may be re-read (at-least-once) or skipped (at-most-once) depending on when the crash happens. Manual commit after processing gives exactly-once semantics: commit only after the ML transformation, database write, or feature computation succeeds.',
