    explanation: 'Kubernetes Secrets are only base64-encoded, not encrypted. Anyone with access to the cluster can decode them. Storing raw Secrets in Git means anyone with repo access sees all credentials. SealedSecrets solve this: you encrypt the Secret into a SealedSecret custom resource at commit time using kubeseal. The SealedSecret controller (running in the cluster) decrypts it and creates the native Secret. The encryption key is only held by the controller. Alternatives: External Secrets Operator (synchronizes secrets from AWS Secrets Manager, GCP Secret Manager, Azure Key Vault), SOPS with Mozilla sops.',
