    ans: "Cilium compiles NetworkPolicy rules into eBPF bytecode programs attached to the pod's cgroup. eBPF runs in kernel-space without context switching, avoiding iptables linear rule traversal. For ML workloads: lower latency (no iptables overhead every packet), identity-based policies (no CIDR management needed when pods restart), and per-flow observability via Hubble for debugging model serving",
    explanation: "eBPF allows sandboxed programs to run in the Linux kernel without changing kernel source. Cilium attaches eBPF programs to cgroups and network interfaces. For ML inference: identity-based policies mean when a model-serving pod restarts (new IP), policies automatically apply via labels. Hubble provides L7 flow logs showing which model version, which client, latency, and response codes — essential for debugging inference pipeline issues.",
