    explanation: "NCCL (NVIDIA Collective Communications Library) handles gradient synchronization across GPUs during distributed training. All-reduce requires every GPU to share gradients with every other GPU — O(n^2) communication. Bandwidth between nodes is the critical constraint. RDMA (Remote Direct Memory Access) bypasses CPU/kernel, reducing latency. GPUDirect RDMA lets GPUs on different nodes communicate directly. For multi-node training, InfiniBand (400 Gbps) is strongly preferred over Ethernet (25-100 Gbps). Use NCCL_DEBUG=INFO and nccl-tests to benchmark and identify bottlenecks.",
