export function getQuestionsByPhase(phase) {
  return QUIZ_BANK.filter(q => q.phase === phase);
}

export function getQuestionsByDifficulty(difficulty) {
  return QUIZ_BANK.filter(q => q.difficulty === difficulty);
}

export function getQuestionsByCategory(category) {
  return QUIZ_BANK.filter(q => q.category === category);
}

export function getRandomQuestions(count = 10, filters = {}) {
  let filtered = [...QUIZ_BANK];
  if (filters.phase) filtered = filtered.filter(q => q.phase === filters.phase);
  if (filters.difficulty) filtered = filtered.filter(q => q.difficulty === filters.difficulty);
  if (filters.category) filtered = filtered.filter(q => q.category === filters.category);
  const shuffled = filtered.sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}

export const QUIZ_BANK = [
  ...QUIZ_BANK_BASE,
  ...QUIZ_BANK_OLD,
];

export function getQuestionsForInterview() {
  return QUIZ_BANK.filter(q => q.category === "interview" || q.category === "system-design" || q.category === "behavioral");
}

